import numpy as np

sample_id = '2026-08-07/T127.csv'
library_id = '2026-08-07/reference_library.csv'

# 1. Get Sample
s_int = None
s_shift = None
for f in files:
    if f['file_id'] == sample_id:
        s_shift = f['table']['raman_shift_cm-1']
        s_int = f['table']['intensity']

# 2. Get PMMA Reference
r_int = None
r_shift = None
for f in files:
    if f['file_id'] == library_id:
        lib_table = f['table']
        # Strip whitespace just in case and check for 'PMMA'
        mats = np.array([str(m).strip() for m in lib_table['material']])
        pmma_mask = (mats == 'PMMA')
        if np.any(pmma_mask):
            r_shift = lib_table['raman_shift_cm-1'][pmma_mask]
            r_int = lib_table['intensity'][pmma_mask]

if s_int is None or r_int is None:
    print("Error: Could not load sample or reference.")
else:
    # Axis check and interpolation
    if not np.array_equal(s_shift, r_shift):
        r_int_interp = np.interp(s_shift, r_shift, r_int)
    else:
        r_int_interp = r_int

    # Cosine Similarity
    def cosine_sim(a, b):
        return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))

    sim = cosine_sim(s_int, r_int_interp)
    print(f"Cosine Similarity: {sim:.4f}")
